DELIMITER $$
--
-- Thủ tục
--
CREATE DEFINER=`root`@`localhost` PROCEDURE `GenerateDummyGroups` ()   BEGIN
    DECLARE i INT DEFAULT 1;
    
    -- KHẮC PHỤC LỖI: Khai báo rõ ràng charset là utf8mb4 cho các biến chuỗi
    DECLARE categoryName VARCHAR(100) CHARACTER SET utf8mb4;
    DECLARE groupName VARCHAR(255) CHARACTER SET utf8mb4;
    DECLARE groupDesc TEXT CHARACTER SET utf8mb4;
    
    DECLARE adminId INT DEFAULT 1; 

    WHILE i <= 200 DO
        -- Gán giá trị
        IF i <= 20 THEN SET categoryName = 'Công Nghệ & Lập Trình';
        ELSEIF i <= 40 THEN SET categoryName = 'Du Lịch & Khám Phá';
        ELSEIF i <= 60 THEN SET categoryName = 'Ẩm Thực & Nấu Ăn';
        ELSEIF i <= 80 THEN SET categoryName = 'Thể Thao & Bóng Đá';
        ELSEIF i <= 100 THEN SET categoryName = 'Âm Nhạc & Giải Trí';
        ELSEIF i <= 120 THEN SET categoryName = 'Học Tập & Sách';
        ELSEIF i <= 140 THEN SET categoryName = 'Bất Động Sản & Nhà Cửa';
        ELSEIF i <= 160 THEN SET categoryName = 'Xe Cộ & Đam Mê';
        ELSEIF i <= 180 THEN SET categoryName = 'Thời Trang & Làm Đẹp';
        ELSE SET categoryName = 'Tâm Sự & Chuyện Đời';
        END IF;

        -- Thực hiện CONCAT (bây giờ sẽ không còn lỗi vì đã cùng charset)
        SET groupName = CONCAT('Cộng đồng ', categoryName, ' ', i);
        SET groupDesc = CONCAT('Đây là nhóm thảo luận về chủ đề ', categoryName, '. Mọi người cùng chia sẻ kiến thức nhé!');

        -- Insert vào bảng
        VALUES (groupName, groupDesc, 'public', adminId, NOW(), NOW());

        SET i = i + 1;
    END WHILE;
END$$

DELIMITER ;

